// === Tab: mySketch ===
// Inspired by Slackmanz - Multiple Neighborhood Cellular Automata (MNCA)
// https://slackermanz.com/understanding-multiple-neighborhood-cellular-automata/

OPC.slider("STYLE",0,0,2,1);
var DEAD = 0;
var ALIVE = 1;
var n = 500;
var brushThickness = 128;
var cells;
var zoom;
var g;

var conditions = {
  0: (status, hood0, hood1) => {
    return status ? hood0 < 19 : hood0 * 2.6 > hood1;
  },
  1: (status, hood0, hood1) => {
    return status ? hood0 < 19 && hood1 < 36 : hood0 * 2.6 > hood1;
  },
  2: (status, hood0, hood1) => {
    return status ? hood0 != hood1 : hood0 * 2.6 > hood1;
  },
};

function setup() {
	p5.disableFriendlyErrors = true;
  const m = max(windowWidth, windowHeight);
  createCanvas(m, m);
  zoom = n / m;

  cells = new Uint8Array(n * n).fill(DEAD);
  g = createGraphics(n, n);
  g.background(0).pixelDensity(1).loadPixels();
}

function draw() {
  background("white");

  const mx = int(constrain((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) * zoom, 0, n - 1));
  const my = int(constrain((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) * zoom, 0, n - 1));

  const b = brushThickness;
  for (dy = -b; dy <= b; dy++) {
    for (dx = -b; dx <= b; dx++) {
      let d = sqrt(dx ** 2 + dy ** 2);
      if (d > b) continue;
      let x = mx + dx;
      let y = my + dy;
      if (x < 0 || x >= n || y < 0 || y >= n) continue;
      cells[x + y * n] = random(5000) < 1 && b - d < 1 ? ALIVE : DEAD;
    }
  }

  const getNextState = conditions[STYLE];
  let next = new Uint8Array(cells);
  for (let y = 4; y < n - 4; y++) {
    for (let x = 4; x < n - 4; x++) {
      const i = x + y * n;

      const hood0 =
        cells[i + 1] +
        cells[i - 1] +
        cells[i - n] +
        cells[i + n] +
        cells[i - 1 - n] +
        cells[i - 1 + n] +
        cells[i + 1 - n] +
        cells[i + 1 + n] +
        cells[i + 2] +
        cells[i + 2 + n] +
        cells[i + 2 - n] +
        cells[i - 2] +
        cells[i - 2 + n] +
        cells[i - 2 - n] +
        cells[i + 2 * n] +
        cells[i + 2 * n - 1] +
        cells[i + 2 * n + 1] +
        cells[i - 2 * n] +
        cells[i - 2 * n + 1] +
        cells[i - 2 * n - 1];

      const hood1 =
        cells[i + 1] +
        cells[i + 2] +
        cells[i + 3] +
        cells[i + 4] +
        cells[i - 1] +
        cells[i - 2] +
        cells[i - 3] +
        cells[i - 4] +
        cells[i - n] +
        cells[i - 2 * n] +
        cells[i - 3 * n] +
        cells[i - 4 * n] +
        cells[i + n] +
        cells[i + 2 * n] +
        cells[i + 3 * n] +
        cells[i + 4 * n] +
        cells[i - n + 1] +
        cells[i - n + 2] +
        cells[i - n + 3] +
        cells[i - n + 4] +
        cells[i - 2 * n + 1] +
        cells[i - 2 * n + 2] +
        cells[i - 2 * n + 3] +
        cells[i - 3 * n + 1] +
        cells[i - 3 * n + 2] +
        cells[i - 4 * n + 1] +
        cells[i + n + 1] +
        cells[i + n + 2] +
        cells[i + n + 3] +
        cells[i + n + 4] +
        cells[i + 2 * n + 1] +
        cells[i + 2 * n + 2] +
        cells[i + 2 * n + 3] +
        cells[i + 3 * n + 1] +
        cells[i + 3 * n + 2] +
        cells[i + 4 * n + 1] +
        cells[i - n - 1] +
        cells[i - n - 2] +
        cells[i - n - 3] +
        cells[i - n - 4] +
        cells[i - 2 * n - 1] +
        cells[i - 2 * n - 2] +
        cells[i - 2 * n - 3] +
        cells[i - 3 * n - 1] +
        cells[i - 3 * n - 2] +
        cells[i - 4 * n - 1] +
        cells[i + n - 1] +
        cells[i + n - 2] +
        cells[i + n - 3] +
        cells[i + n - 4] +
        cells[i + 2 * n - 1] +
        cells[i + 2 * n - 2] +
        cells[i + 2 * n - 3] +
        cells[i + 3 * n - 1] +
        cells[i + 3 * n - 2] +
        cells[i + 4 * n - 1];

      state = getNextState(cells[i], hood0, hood1);
      next[i] = state;
      g.pixels[i * 4 + 3] = state ? 255 : 0;
    }
  }
  cells = next;
  g.updatePixels();
  image(g, 0, 0, width, height);
}

